-- Keep privileged implementations outside the exposed API schema.
GRANT USAGE ON SCHEMA private TO authenticated;
ALTER FUNCTION public.event_actor_permission() SET SCHEMA private;
ALTER FUNCTION public.admin_upsert_event_volunteer(text, text) SET SCHEMA private;
ALTER FUNCTION public.admin_set_event_volunteer_active(uuid, boolean) SET SCHEMA private;
ALTER FUNCTION public.admin_set_snack_policy(text) SET SCHEMA private;
ALTER FUNCTION public.event_scan_pass(uuid, text, integer) SET SCHEMA private;
ALTER FUNCTION public.event_operations_summary() SET SCHEMA private;
ALTER FUNCTION public.event_search_participants(text) SET SCHEMA private;
ALTER FUNCTION public.event_operations_export() SET SCHEMA private;
REVOKE ALL ON FUNCTION private.event_actor_permission() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.admin_upsert_event_volunteer(text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.admin_set_event_volunteer_active(uuid, boolean) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.admin_set_snack_policy(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.event_scan_pass(uuid, text, integer) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.event_operations_summary() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.event_search_participants(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION private.event_operations_export() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION private.event_actor_permission() TO authenticated;
GRANT EXECUTE ON FUNCTION private.admin_upsert_event_volunteer(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION private.admin_set_event_volunteer_active(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION private.admin_set_snack_policy(text) TO authenticated;
GRANT EXECUTE ON FUNCTION private.event_scan_pass(uuid, text, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION private.event_operations_summary() TO authenticated;
GRANT EXECUTE ON FUNCTION private.event_search_participants(text) TO authenticated;
GRANT EXECUTE ON FUNCTION private.event_operations_export() TO authenticated;
CREATE OR REPLACE FUNCTION public.event_actor_permission() RETURNS text LANGUAGE sql STABLE SECURITY INVOKER SET search_path = '' AS $$ SELECT private.event_actor_permission() $$;
CREATE OR REPLACE FUNCTION public.admin_upsert_event_volunteer(p_email text, p_permission text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.admin_upsert_event_volunteer(p_email, p_permission) $$;
CREATE OR REPLACE FUNCTION public.admin_set_event_volunteer_active(p_user_id uuid, p_active boolean) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.admin_set_event_volunteer_active(p_user_id, p_active) $$;
CREATE OR REPLACE FUNCTION public.admin_set_snack_policy(p_policy text) RETURNS void LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT private.admin_set_snack_policy(p_policy) $$;
CREATE OR REPLACE FUNCTION public.event_scan_pass(p_token uuid, p_action text, p_event_day integer DEFAULT 1) RETURNS TABLE(result text, participant_name text, application_number text, participant_email text, occurred_at timestamptz, snack_policy text) LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT * FROM private.event_scan_pass(p_token, p_action, p_event_day) $$;
CREATE OR REPLACE FUNCTION public.event_operations_summary() RETURNS TABLE(total_registered bigint, checked_in bigint, snacks_distributed bigint, pending_checkin bigint, snack_policy text, volunteers jsonb, recent_activity jsonb) LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT * FROM private.event_operations_summary() $$;
CREATE OR REPLACE FUNCTION public.event_search_participants(p_query text DEFAULT '') RETURNS TABLE(registration_id uuid, participant_name text, application_number text, participant_email text, checked_in_at timestamptz, snack_claims bigint) LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT * FROM private.event_search_participants(p_query) $$;
CREATE OR REPLACE FUNCTION public.event_operations_export() RETURNS TABLE(participant_name text, participant_email text, application_number text, checked_in_at timestamptz, checked_in_by_email text, snack_claims bigint) LANGUAGE sql SECURITY INVOKER SET search_path = '' AS $$ SELECT * FROM private.event_operations_export() $$;
REVOKE ALL ON FUNCTION public.event_actor_permission() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_upsert_event_volunteer(text, text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_set_event_volunteer_active(uuid, boolean) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.admin_set_snack_policy(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.event_scan_pass(uuid, text, integer) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.event_operations_summary() FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.event_search_participants(text) FROM PUBLIC, anon;
REVOKE ALL ON FUNCTION public.event_operations_export() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.event_actor_permission() TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_upsert_event_volunteer(text, text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_set_event_volunteer_active(uuid, boolean) TO authenticated;
GRANT EXECUTE ON FUNCTION public.admin_set_snack_policy(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.event_scan_pass(uuid, text, integer) TO authenticated;
GRANT EXECUTE ON FUNCTION public.event_operations_summary() TO authenticated;
GRANT EXECUTE ON FUNCTION public.event_search_participants(text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.event_operations_export() TO authenticated;